/*
 * A329432  Irregular triangular array, read by rows: row n shows the
 *          coefficients of the polynomial p(n,x) defined in Comments.
 * https://oeis.org/A329432
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 13, u32 n <= 23, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * The OEIS sequence A329432 is generated by the following construction
 *
 *  u0(x) = 1
 *  u1(x) = 1 + 2 x
 *  u_{k+1}(x) = 2 * u_k(x)^2 + 1          (k ≥ 1)
 *
 * The sequence {a(n)} is obtained by concatenating, in order,
 * the coefficients of the polynomials u0, u1, u2, u3, …,
 * each coefficient being taken in ascending order of degree.
 *
 * For example:
 *  u0(x)     = 1                →  [1]
 *  u1(x)     = 1 + 2x           →  [1, 2]
 *  u2(x)     = 3 + 8x + 8x^2    →  [3, 8, 8]
 *  u3(x)     = 19 + 96x + 224x^2 + 256x^3 + 128x^4
 *               →  [19, 96, 224, 256, 128]
 *  ...
 *
 * The sequence a(n) is exactly the concatenation of those coefficient
 * vectors.
 */

#include <stdlib.h>

/* Static state for on‑demand generation of the polynomials */
static size_t   poly_count = 0;       /* number of polynomials stored      */
static size_t   poly_cap   = 0;       /* current allocation capacity      */
static seq_t **polys      = NULL;     /* array of pointers to coefficient arrays */
static size_t *len        = NULL;     /* number of coefficients per polynomial  */
static size_t *cum_len    = NULL;     /* cumulative lengths: cum_len[i] = sum_{j≤i} len[j] */

/* --------------------------------------------------------------- */
/*  Ensure that the state has been initialised (pol0 and pol1)      */
/* --------------------------------------------------------------- */
static void
ensure_initialised(void)
{
    if (poly_count != 0)
        return;                                 /* already initialised */

    /* start with capacity for 4 polynomials */
    poly_cap = 4;
    polys   = (seq_t **)malloc(poly_cap * sizeof(seq_t*));
    len     = (size_t*)malloc(poly_cap * sizeof(size_t));
    cum_len = (size_t*)malloc(poly_cap * sizeof(size_t));

    /* ----------  polynomial u0  ---------- */
    polys[0] = (seq_t*)malloc(sizeof(seq_t));
    polys[0][0] = (seq_t)1;
    len[0] = 1;
    cum_len[0] = 1;
    poly_count = 1;

    /* ----------  polynomial u1  ---------- */
    polys[1] = (seq_t*)malloc(2 * sizeof(seq_t));
    polys[1][0] = (seq_t)1;
    polys[1][1] = (seq_t)2;
    len[1] = 2;
    cum_len[1] = cum_len[0] + len[1]; /* 1 + 2 = 3 */
    poly_count = 2;
}

/* --------------------------------------------------------------- */
/*  Generate the next polynomial from the last one:                 */
/*   u_{k+1}(x) = 2 * u_k(x)^2 + 1                                  */
/* --------------------------------------------------------------- */
static void
generate_next(void)
{
    size_t prev = poly_count - 1;              /* index of last polynomial */
    size_t prev_len = len[prev];
    size_t new_len = 2 * prev_len - 1;         /* degree doubles -> 2*len -1 */

    /* re‑allocate storage if necessary */
    if (poly_count == poly_cap) {
        poly_cap <<= 1;                       /* double capacity */
        polys   = (seq_t **)realloc(polys,   poly_cap * sizeof(seq_t*));
        len     = (size_t*)realloc(len,     poly_cap * sizeof(size_t));
        cum_len = (size_t*)realloc(cum_len, poly_cap * sizeof(size_t));
    }

    /* allocate new polynomial */
    seq_t *poly = (seq_t*)malloc(new_len * sizeof(seq_t));
    for (size_t i = 0; i < new_len; ++i) poly[i] = 0;

    /* u_{k+1} = 2 * (u_k)^2 + 1 */
    for (size_t i = 0; i < prev_len; ++i) {
        seq_t ai = polys[prev][i];
        for (size_t j = 0; j < prev_len; ++j) {
            poly[i + j] += (seq_t)2 * ai * polys[prev][j];
        }
    }
    poly[0] += (seq_t)1;                      /* add the constant term */

    /* store it */
    polys[poly_count] = poly;
    len[poly_count]   = new_len;
    cum_len[poly_count] = cum_len[poly_count - 1] + new_len;
    ++poly_count;
}

/* --------------------------------------------------------------- */
/*  Find the polynomial and local index that contain the n-th term  */
/* --------------------------------------------------------------- */
static void
find_location(idx_t n, size_t *poly_idx, size_t *local_idx)
{
    /* expand the state until it covers n */
    while (n >= (idx_t)cum_len[poly_count - 1]) {
        generate_next();
    }

    /* locate the polynomial */
    size_t idx = 0;
    while (idx < poly_count && n >= (idx_t)cum_len[idx]) {
        ++idx;
    }

    *poly_idx  = idx;
    if (idx == 0)
        *local_idx = (size_t)n;
    else
        *local_idx = (size_t)(n - (idx_t)cum_len[idx - 1]);
}

/* --------------------------------------------------------------- */
/*  Public entry point required by the exercise                   */
/* --------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* initialise static state on first call */
    ensure_initialised();

    /* locate the desired coefficient */
    size_t poly_idx, local_idx;
    find_location(n, &poly_idx, &local_idx);

    return polys[poly_idx][local_idx];
}
